const target=document.querySelector('#reportContent');let report=null;try{report=JSON.parse(localStorage.getItem('advance-exam-report')||'null')}catch{};
const formatTime=ms=>{const seconds=Math.floor(Math.max(0,ms)/1000);return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')};const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
if(!report||!Array.isArray(report.scores)){target.innerHTML='<section class="report-section empty">还没有模拟考试记录。完成一次考场模拟后，这里会生成报告。<div class="actions"><a class="primary" href="exam.html">开始模拟考试</a></div></section>'}else{
  const totalScore=report.scores.reduce((a,b)=>a+b,0),maxScore=report.maxPoints.reduce((a,b)=>a+b,0),typeNames=['单选题','多选题','简答题','综合题'];
  const totals=typeNames.map(type=>report.durations.reduce((sum,ms,i)=>sum+(report.types[i]===type?ms:0),0)),topTime=Math.max(1000,...totals);
  const typeRows=typeNames.map((type,i)=>'<div class="time-row"><span>'+type+'</span><div class="bar"><span style="width:'+Math.max(3,Math.round(totals[i]/topTime*100))+'%"></span></div><span>'+formatTime(totals[i])+'</span></div>').join('');
  const questionRows=report.scores.map((score,i)=>{const status=score===report.maxPoints[i]?'full':score>0?'partial':'zero';return '<div class="question-result"><div class="question-circle '+status+'" aria-label="第 '+(i+1)+' 题，得 '+score+' 分">'+String(i+1).padStart(2,'0')+'</div><p>'+report.types[i]+'</p><small>'+score+' / '+report.maxPoints[i]+' 分</small></div>'}).join('');
  const strong=report.scores.map((score,i)=>score===report.maxPoints[i]?report.types[i]:null).filter(Boolean),weak=report.scores.map((score,i)=>score<report.maxPoints[i]?report.knowledge[i]:null).filter(Boolean);
  const strengths=strong.length?'你在'+strong.join('、')+'中拿到了满分，说明这些题目的处理很稳。':'这次没有满分题也没关系，你已经留下了一次完整的练习记录。';
  const improve=weak.length?'下次可以优先复习：'+[...new Set(weak)].join('、')+'。从其中一个点开始，再做几道同类题巩固。':'各题都拿到了满分，可以尝试难度更高的综合题。';
  const encouragement=totalScore>=80?'今天的发挥很扎实。保持复盘的习惯，你的稳定性会越来越好。':totalScore>=50?'你已经找到自己较稳的部分，也看见了需要加强的知识点。把问题拆小，下一次会更从容。':'这次模拟让薄弱点变得清楚了。先挑一个知识点弄懂，再来练习，进步会逐渐显现。';
  target.innerHTML='<div class="score-card"><div class="score-box"><strong>'+totalScore+' / '+maxScore+'</strong><span>模拟得分</span></div><div class="score-box"><strong>'+formatTime(report.totalMs)+'</strong><span>总做题时长</span></div></div><section class="report-section"><h2>各题型做题时长</h2><div class="time-rows">'+typeRows+'</div></section><section class="report-section"><h2>每题得分</h2><div class="question-grid">'+questionRows+'</div><div class="legend"><span><i style="background:#b4d9bd"></i>满分</span><span><i style="background:#eedba1"></i>部分得分</span><span><i style="background:#edc5c5"></i>未得分</span></div></section><section class="report-section"><h2>你的模拟分析</h2><div class="analysis-grid"><div class="analysis-item"><h3>做得好的地方</h3>'+escapeHtml(strengths)+'</div><div class="analysis-item"><h3>可以加强的知识点</h3>'+escapeHtml(improve)+'</div></div><p class="encourage">'+escapeHtml(encouragement)+'</p><p style="color:#9aa8ba;font-size:12px;margin:12px 0 0">简答题与综合题在原型中依据关键词模拟评分。</p></section><div class="actions"><a href="index.html?view=home">返回首页</a><a class="primary" href="exam.html">再练一次</a></div>';
}
